CREATE TABLE public.evidence_links (
	tenant_id UUID NOT NULL, 
	id UUID DEFAULT gen_random_uuid() NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	claim_id UUID NOT NULL, 
	kind VARCHAR(24) NOT NULL, 
	ref TEXT NOT NULL, 
	start_ms BIGINT, 
	end_ms BIGINT, 
	excerpt_hash VARCHAR(64) NOT NULL, 
	score FLOAT, 
	CONSTRAINT pk_evidence_links PRIMARY KEY (tenant_id, id), 
	CONSTRAINT fk_evidence_links_tenant_id_claim_id_claims FOREIGN KEY(tenant_id, claim_id) REFERENCES public.claims (tenant_id, id), 
	CHECK (kind IN ('audio_span','transcript_turn','fhir_resource','label_section','rule')), 
	CHECK (excerpt_hash ~ '^[0-9a-f]{64}$'), 
	CHECK ((start_ms IS NULL AND end_ms IS NULL) OR (start_ms IS NOT NULL AND end_ms IS NOT NULL AND start_ms >= 0 AND end_ms > start_ms)), 
	CHECK (score IS NULL OR score BETWEEN 0 AND 1)
)
